// ============================================================
// SCRIPT: Send task record to Obsidian via n8n webhook
// TRIGGER: Automation trigger on Taken table (record enters "Tasks Iris" view)
// TABLES: Taken (tblW5PkBL4mysdN7t)
// DESCRIPTION: Reads task fields from the triggering record and POSTs
//              them to the n8n webhook, which generates a TaskNotes .md
//              file in Google Drive. Fire-and-forget — no response handling.
// ============================================================

const TABLE_ID          = "tblW5PkBL4mysdN7t";
const FLD_TITLE         = "fldEqow62GYNmDB25"; // Taak titel (singleLineText)
const FLD_PRIORITY      = "fldOdj6ciljsoLdDp"; // Prioriteit (singleSelect)
const FLD_DUE_DATE      = "fldV1POvR5BiufpEd"; // Einddatum (date)
const FLD_DESCRIPTION   = "fldwK4oXwt9wMEVdq"; // Omschrijving (richText)
const FLD_URL           = "fldZ9hO1xf6s2c7UN"; // Interface URL (formula)
const FLD_PROJECTS      = "fldZJtL9yvprQjEtY"; // Project naam (from Project) (lookupValues)

const WEBHOOK_URL = "https://picoo.app.n8n.cloud/webhook/4c99be7c-b31b-4de0-9872-ed70631bb56b";

async function main() {
  const { recordId } = input.config();
  const table = base.getTable(TABLE_ID);
  const record = await table.selectRecordAsync(recordId, {
    fields: [FLD_TITLE, FLD_PRIORITY, FLD_DUE_DATE, FLD_DESCRIPTION, FLD_URL, FLD_PROJECTS]
  });

  const title       = record.getCellValueAsString(FLD_TITLE);
  const priority    = record.getCellValue(FLD_PRIORITY)?.name || null;
  const due_dateRaw = record.getCellValue(FLD_DUE_DATE);
  const due_date    = due_dateRaw ? due_dateRaw.slice(0, 10) : null;
  const description = record.getCellValueAsString(FLD_DESCRIPTION) || null;
  const url         = record.getCellValueAsString(FLD_URL);
  const projectsRaw = record.getCellValue(FLD_PROJECTS);
  const projects    = projectsRaw?.length ? projectsRaw.join(", ") : null;

  const payload = { title, url };
  if (priority)    payload.priority    = priority;
  if (due_date)    payload.due_date    = due_date;
  if (description) payload.description = description;
  if (projects)    payload.projects    = projects;

  await fetch(WEBHOOK_URL, {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify(payload)
  });
}

await main();
